// ─────────────────────────────────────────────
// SMALL UI COMPONENTS
// ─────────────────────────────────────────────
function Badge({ label }) {
  const c = STATUS_COLORS[label] || { bg:"#F5F5F5", fg:"#888" };
  return (
    <span style={{ display:"inline-flex", alignItems:"center", gap:4, padding:"3px 9px", borderRadius:20, background:c.bg, color:c.fg, fontSize:12, fontWeight:600, whiteSpace:"nowrap" }}>
      <span style={{ width:5, height:5, borderRadius:"50%", background:c.fg, flexShrink:0 }} />
      {label}
    </span>
  );
}

function Card({ children, style }) {
  return (
    <div style={{ background:"#fff", borderRadius:12, border:"1px solid #EAECF0", padding:24, ...style }}>
      {children}
    </div>
  );
}

function Gauge({ pct, color }) {
  return (
    <div style={{ display:"flex", alignItems:"center", gap:7 }}>
      <div style={{ width:52, height:4, borderRadius:2, background:"#F2F4F7", overflow:"hidden" }}>
        <div style={{ width:pct + "%", height:"100%", background:color, borderRadius:2 }} />
      </div>
      <span style={{ fontSize:13, fontWeight:700, color }}>{pct}</span>
    </div>
  );
}

function TH({ children }) {
  return (
    <th style={{ padding:"10px 14px", textAlign:"left", fontSize:12, color:"#667085", fontWeight:600, borderBottom:"2px solid #F2F4F7", whiteSpace:"nowrap", background:"#F9FAFB" }}>
      {children}
    </th>
  );
}

function TD({ children, style }) {
  return <td style={{ padding:"12px 14px", ...style }}>{children}</td>;
}

function TR({ children }) {
  const [hover, setHover] = useState(false);
  return (
    <tr
      style={{ borderBottom:"1px solid #F9FAFB", background:hover ? "#FAFAFA" : "#fff" }}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
    >
      {children}
    </tr>
  );
}

function PageHeader({ title, sub }) {
  return (
    <div style={{ marginBottom:24 }}>
      <h1 style={{ fontSize:22, fontWeight:800, color:"#101828", margin:0, letterSpacing:"-0.5px" }}>{title}</h1>
      {sub && <p style={{ margin:"4px 0 0", fontSize:13, color:"#98A2B3" }}>{sub}</p>}
    </div>
  );
}

function KpiCard({ label, value, sub, trend, accent, iconD }) {
  const col = accent || "#2C6BED";
  return (
    <Card style={{ display:"flex", flexDirection:"column", gap:12 }}>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
        <div style={{ background:col + "20", borderRadius:10, padding:10 }}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke={col} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
            <path d={iconD} />
          </svg>
        </div>
        {trend !== undefined && (
          <span style={{ fontSize:12, fontWeight:600, color:trend >= 0 ? "#12B76A" : "#F04438" }}>
            {trend >= 0 ? "+" : ""}{trend}%
          </span>
        )}
      </div>
      <div>
        <div style={{ fontSize:13, color:"#667085", fontWeight:500, marginBottom:4 }}>{label}</div>
        <div style={{ fontSize:26, fontWeight:800, color:"#101828", letterSpacing:"-0.5px" }}>{value}</div>
        {sub && <div style={{ fontSize:12, color:"#98A2B3", marginTop:3 }}>{sub}</div>}
      </div>
    </Card>
  );
}

function BtnPrimary({ label, onClick }) {
  return (
    <button onClick={onClick} style={{ display:"flex", alignItems:"center", gap:6, height:36, padding:"0 14px", borderRadius:8, border:"none", background:"#2C6BED", color:"#fff", fontSize:13, fontWeight:600, cursor:"pointer", whiteSpace:"nowrap" }}>
      {label}
    </button>
  );
}

function BtnSecondary({ label, onClick }) {
  return (
    <button onClick={onClick} style={{ display:"flex", alignItems:"center", gap:6, height:36, padding:"0 14px", borderRadius:8, border:"1px solid #EAECF0", background:"#fff", color:"#344054", fontSize:13, fontWeight:600, cursor:"pointer", whiteSpace:"nowrap" }}>
      {label}
    </button>
  );
}

function Ico({ d, size = 16, color = "#667085", stroke = 2 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round">
      <path d={d} />
    </svg>
  );
}

