function NewStoreModal({ onClose }) {
  const [step, setStep] = useState(1);
  const TOTAL = 3;

  function Field({ label, placeholder, type = "text", required, half }) {
    return (
      <div style={{ marginBottom:12, gridColumn: half ? "span 1" : "span 2" }}>
        <label style={{ display:"block", fontSize:12, fontWeight:600, color:"#344054", marginBottom:4 }}>
          {label}{required && <span style={{ color:"#F04438", marginLeft:2 }}>*</span>}
        </label>
        <input type={type} placeholder={placeholder} style={{ width:"100%", height:36, border:"1px solid #D0D5DD", borderRadius:8, padding:"0 12px", fontSize:13, color:"#101828", outline:"none", boxSizing:"border-box" }} />
      </div>
    );
  }

  function SelectField({ label, options, required, half }) {
    return (
      <div style={{ marginBottom:12, gridColumn: half ? "span 1" : "span 2" }}>
        <label style={{ display:"block", fontSize:12, fontWeight:600, color:"#344054", marginBottom:4 }}>
          {label}{required && <span style={{ color:"#F04438", marginLeft:2 }}>*</span>}
        </label>
        <select style={{ width:"100%", height:36, border:"1px solid #D0D5DD", borderRadius:8, padding:"0 12px", fontSize:13, color:"#101828", outline:"none", background:"#fff", boxSizing:"border-box" }}>
          <option value="">선택하세요</option>
          {options.map((o) => <option key={o}>{o}</option>)}
        </select>
      </div>
    );
  }

  const stepLabels = ["기본 정보", "사업자·계좌 정보", "계약 조건"];

  return (
    <div style={{ position:"fixed", inset:0, background:"rgba(16,24,40,0.45)", zIndex:300, display:"flex", alignItems:"center", justifyContent:"center" }}>
      <div style={{ width:520, background:"#fff", borderRadius:16, boxShadow:"0 20px 60px rgba(0,0,0,0.2)", overflow:"hidden" }}>
        {/* Header */}
        <div style={{ padding:"18px 22px", borderBottom:"1px solid #EAECF0", display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
          <div>
            <div style={{ fontSize:16, fontWeight:800, color:"#101828" }}>신규 매장 등록</div>
            <div style={{ fontSize:12, color:"#98A2B3", marginTop:3 }}>Step {step}/{TOTAL} — {stepLabels[step-1]}</div>
          </div>
          <button onClick={onClose} style={{ width:30, height:30, borderRadius:"50%", border:"1px solid #EAECF0", background:"#fff", cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" }}>
            <Ico d={D_CLOSE} size={14} />
          </button>
        </div>

        {/* Step bar */}
        <div style={{ padding:"12px 22px 0", display:"flex", gap:6 }}>
          {[1,2,3].map((s) => (
            <div key={s} style={{ flex:1, height:4, borderRadius:2, background: s<=step ? "#2C6BED" : "#F2F4F7" }} />
          ))}
        </div>

        {/* Form */}
        <div style={{ padding:"16px 22px", maxHeight:400, overflowY:"auto" }}>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:"0 12px" }}>
            {step === 1 && (
              <>
                <Field label="매장명" placeholder="예) 강남역점" required />
                <Field label="매장 코드" placeholder="자동 생성 (BRCF-XXX)" half />
                <SelectField label="권역" options={REGIONS} required half />
                <Field label="지역 (시·군·구)" placeholder="서울 강남구" required half />
                <SelectField label="매장 유형" options={STORE_TYPES} required half />
                <SelectField label="매장 등급" options={["A","B","C","D"]} required half />
                <SelectField label="배정 SV" options={SV_LIST.map(sv => sv.name)} required half />
                <SelectField label="영업 상태" options={["영업준비","영업중"]} required half />
                <Field label="매장 주소" placeholder="도로명 주소" required />
                <Field label="상세 주소" placeholder="층·호수" />
                <Field label="대표 연락처" placeholder="02-0000-0000" type="tel" required half />
              </>
            )}
            {step === 2 && (
              <>
                <Field label="사업자 등록번호" placeholder="000-00-00000" required />
                <Field label="대표자명" placeholder="홍길동" required half />
                <Field label="업종" placeholder="커피 전문점" half />
                <Field label="은행명" placeholder="신한은행" required half />
                <Field label="계좌번호" placeholder="000-000-000000" required half />
                <Field label="예금주" placeholder="홍길동" required half />
              </>
            )}
            {step === 3 && (
              <>
                <Field label="계약 시작일" type="date" required half />
                <Field label="계약 종료일" type="date" required half />
                <Field label="로열티 (%)" placeholder="5" type="number" required half />
                <Field label="오픈 예정일" type="date" required half />
                <div style={{ gridColumn:"span 2", marginBottom:12 }}>
                  <label style={{ display:"block", fontSize:12, fontWeight:600, color:"#344054", marginBottom:4 }}>전자계약 문서 첨부</label>
                  <label style={{ display:"block", border:"2px dashed #D0D5DD", borderRadius:10, padding:"22px", textAlign:"center", background:"#FAFAFA", cursor:"pointer" }}>
                    <Ico d={D_UP} size={24} color="#98A2B3" />
                    <div style={{ fontSize:13, color:"#667085", marginTop:8 }}>파일을 드래그하거나 클릭하여 업로드</div>
                    <div style={{ fontSize:11, color:"#98A2B3", marginTop:3 }}>PDF, DOCX (최대 10MB)</div>
                    <input type="file" accept=".pdf,.docx" style={{ display:"none" }} />
                  </label>
                </div>
              </>
            )}
          </div>
        </div>

        {/* Footer */}
        <div style={{ padding:"14px 22px", borderTop:"1px solid #EAECF0", display:"flex", justifyContent:"space-between" }}>
          <button onClick={() => step > 1 ? setStep(step-1) : onClose()} style={{ height:38, padding:"0 20px", borderRadius:8, border:"1px solid #EAECF0", background:"#fff", color:"#344054", fontSize:13, fontWeight:600, cursor:"pointer" }}>
            {step === 1 ? "취소" : "이전"}
          </button>
          <button onClick={() => step < TOTAL ? setStep(step+1) : onClose()} style={{ height:38, padding:"0 24px", borderRadius:8, border:"none", background:"#2C6BED", color:"#fff", fontSize:13, fontWeight:600, cursor:"pointer" }}>
            {step === TOTAL ? "✓ 등록 완료" : "다음 →"}
          </button>
        </div>
      </div>
    </div>
  );
}

